import csv, sqlite3
conn = sqlite3.connect('db/hero_power.db')
cur = conn.cursor()
cur.execute('SELECT hero_id FROM hero_power WHERE power_id = 18')
super_str_hero_ids = set(row[0] for row in cur.fetchall())
conn.close()
count = 0
with open('csv/superhero.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        hid = int(row['id'])
        if hid in super_str_hero_ids:
            h = row['height_cm']
            if h and h != '':
                try:
                    if int(h) > 200:
                        count += 1
                except:
                    pass
print(count)

